  FOR guard_name IN SELECT unnest(ARRAY['allegro_oauth_recovery_guards','b2b_credit_guards','b2b_invoice_guards','buyer_address_guards','catalog_stock_control_guards','competitor_observation_guards','fa3_draft_guards','financial_return_upgrade_valid','local_invoice_guards','packed_label_print_guards','parcel_physical_wz_valid','product_rule_schedule_guards','stocktake_adjustment_guards','warehouse_automatic_wz_guards','warehouse_wz_issuer_guards']) LOOP EXECUTE format('SELECT public.%I()',guard_name) INTO guard_ok;IF guard_ok IS DISTINCT FROM true THEN RETURN false;END IF;END LOOP;
