CREATE OR REPLACE FUNCTION public.large_import173_valid()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c public.large_import173_certificate%ROWTYPE;p jsonb;
BEGIN
 IF EXISTS(SELECT FROM public.migrations m187 WHERE m187.name='187_durable_original_writer_epoch') OR EXISTS(SELECT FROM pg_namespace WHERE nspname='ordinary187_private') OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary187_')) THEN
  RETURN public.ordinary187_valid();
 END IF;
 IF EXISTS(SELECT FROM public.migrations m186 WHERE m186.name='186_core_review_alias_binding') OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary186_')) THEN
  RETURN public.ordinary186_valid();
 END IF;
 IF EXISTS(SELECT FROM public.migrations m185 WHERE m185.name='185_private_keeper_generation') OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary185_')) THEN
  RETURN public.ordinary185_valid();
 END IF;
 --182: full integrity is cold; every native IAM admission remains fresh.
 IF EXISTS(SELECT FROM public.migrations AS migration182 WHERE migration182.name='182_cold_schema_runtime_admission') OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'ordinary182_')) THEN
  IF to_regprocedure('public.ordinary182_valid()') IS NULL OR (SELECT encode(sha256(convert_to(prosrc,'UTF8')),'hex') FROM pg_proc WHERE oid=to_regprocedure('public.ordinary182_valid()')) IS DISTINCT FROM '2f35ece3fa8206553e2b92d1bf1940872c795eaa95d7423214a4c83f29679d8a' THEN RETURN false;END IF;
  RETURN public.ordinary182_valid();
 END IF;
