$function$

CREATE OR REPLACE FUNCTION public.large_import_core_review173_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE j public.large_import_jobs173%ROWTYPE; old_review public.large_import_core_reviews173%ROWTYPE;
 state jsonb; r jsonb; b jsonb; c jsonb; page jsonb; resolution jsonb; row_json jsonb; native_row jsonb;
 canonical_scope text; projection jsonb; projected_batches jsonb:='[]'::jsonb; actual_rows jsonb; request_text text; rows_text text;
 p public.catalog_file_import_previews%ROWTYPE; nr public.catalog_file_import_rows%ROWTYPE;
 n integer:=0; page_no integer; count_rows integer; total_rows integer:=0;
 lock_key bigint; ref jsonb; ids uuid[]:=ARRAY[]::uuid[]; batches integer[]:=ARRAY[]::integer[];
 links jsonb:='[]'::jsonb; target uuid; old_revision bigint;
BEGIN
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION 'CoreReview history is append only' USING ERRCODE='23514'; END IF;
 -- SECURITY DEFINER is solely for trigger-local reads/private predicates; no callable app EXECUTE grants.
 -- This role/tenant evidence is not a genuine current Actor/session/IAM substitute.
 IF NOT (current_setting('role',true)='dyna_app' OR current_setting('role',true)='none' AND session_user='dyna_app')
 OR nullif(current_setting('app.tenant_id',true),'')::uuid IS DISTINCT FROM NEW.tenant_id
 THEN RAISE EXCEPTION 'CoreReview requires native app role and tenant' USING ERRCODE='42501'; END IF;
 lock_key:=hashtextextended('large-import173:'||NEW.tenant_id::text||':'||NEW.job_id::text,0);
 IF NOT EXISTS(SELECT 1 FROM pg_catalog.pg_locks l WHERE l.locktype='advisory'
 AND l.pid=pg_backend_pid() AND l.database=(SELECT oid FROM pg_catalog.pg_database WHERE datname=current_database())
 AND l.mode='ExclusiveLock' AND l.granted IS TRUE AND l.objsubid=1
 AND l.classid::bigint=((lock_key>>32)&4294967295::bigint) AND l.objid::bigint=(lock_key&4294967295::bigint))
 THEN RAISE EXCEPTION 'CoreReview requires exact owned Job advisory key' USING ERRCODE='23514'; END IF;
 SELECT * INTO STRICT j FROM public.large_import_jobs173 WHERE tenant_id=NEW.tenant_id AND id=NEW.job_id FOR UPDATE;
 IF j.actor_id IS DISTINCT FROM NEW.actor_id OR j.api_key_id IS DISTINCT FROM NEW.api_key_id
 OR j.revision IS DISTINCT FROM NEW.job_revision OR j.lease_fence IS DISTINCT FROM NEW.lease_fence
 OR j.lease_token IS NULL OR j.leased_at IS NULL
 THEN RAISE EXCEPTION 'CoreReview current Job owner/revision/fence differs' USING ERRCODE='23514'; END IF;
 -- lease_token comparison against the private caller token is additionally enforced by the same-client adapter.
 -- No token is stored in immutable review evidence; actor/API-key presence is not authenticated authority.
 state:=j.state_text::jsonb; r:=NEW.review_text::jsonb;
 IF public.large_import_core_review173_keys(r,ARRAY['schema','revision','source_plan_hash','raw','parsing_spec','batches','aggregate_scope_hash','approved_scope_hash']) IS DISTINCT FROM true
 OR r->>'schema' IS DISTINCT FROM 'large-import-core-review/v1'
 OR jsonb_typeof(r->'revision') IS DISTINCT FROM 'number' OR (r->>'revision') !~ '^(0|[1-9][0-9]*)$'
 OR (r->>'revision')::numeric IS DISTINCT FROM NEW.revision::numeric
 OR r->>'source_plan_hash' IS DISTINCT FROM j.plan_hash OR public.large_import_core_review173_ref(r->'raw') IS DISTINCT FROM true OR r->'raw' IS DISTINCT FROM state->'raw'
 OR r->'parsing_spec' IS DISTINCT FROM state->'parsing_spec' OR state->'approved' IS DISTINCT FROM 'true'::jsonb
 OR jsonb_typeof(r->'batches') IS DISTINCT FROM 'array'
 OR jsonb_array_length(r->'batches') IS DISTINCT FROM jsonb_array_length(state->'core') OR jsonb_array_length(r->'batches')=0
 OR r->>'aggregate_scope_hash' IS DISTINCT FROM NEW.aggregate_scope_hash
 OR r->'approved_scope_hash' IS DISTINCT FROM coalesce(to_jsonb(NEW.approved_scope_hash),'null'::jsonb)
 OR jsonb_array_length(NEW.request_texts) IS DISTINCT FROM jsonb_array_length(r->'batches')
 OR jsonb_array_length(NEW.row_texts) IS DISTINCT FROM jsonb_array_length(r->'batches')
 THEN RAISE EXCEPTION 'CoreReview closed envelope/Job scope differs' USING ERRCODE='23514'; END IF;
 FOR b IN SELECT value FROM jsonb_array_elements(r->'batches') LOOP
  c:=state->'core'->n;
  IF public.large_import_core_review173_keys(b,ARRAY['index','preview_id','scope_hash','preview_key','execute_key','request_hash','rows_hash','resolution','eligibility','preview']) IS DISTINCT FROM true
  OR b->'index' IS DISTINCT FROM to_jsonb(n)
  OR b->>'preview_id' IS DISTINCT FROM c#>>'{preview,ack,head,id}'
  OR b->>'scope_hash' IS DISTINCT FROM c#>>'{preview,ack,head,scope_hash}'
  OR b->>'preview_key' IS DISTINCT FROM c->>'previewKey' OR b->>'execute_key' IS DISTINCT FROM c->>'executeKey'
  OR jsonb_typeof(b->'request_hash') IS DISTINCT FROM 'string' OR (b->>'request_hash') !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(b->'rows_hash') IS DISTINCT FROM 'string' OR (b->>'rows_hash') !~ '^[a-f0-9]{64}$'
  OR public.large_import_core_review173_keys(b#>'{preview,ack}',ARRAY['head','witness','reused']) IS DISTINCT FROM true
  OR public.large_import_core_review173_ref(b#>'{preview,ack,witness}') IS DISTINCT FROM true
  OR jsonb_typeof(b#>'{preview,ack,reused}') IS DISTINCT FROM 'boolean'
  OR public.large_import_core_review173_keys(b->'preview',ARRAY['ack','pages']) IS DISTINCT FROM true
  OR b#>'{preview,ack}' IS DISTINCT FROM c#>'{preview,ack}'
  OR jsonb_typeof(b#>'{preview,pages}') IS DISTINCT FROM 'array'
  OR jsonb_array_length(b#>'{preview,pages}') NOT BETWEEN 1 AND 5
  OR jsonb_typeof(b->'resolution') IS DISTINCT FROM 'array'
  THEN RAISE EXCEPTION 'CoreReview batch/native keys differ' USING ERRCODE='23514'; END IF;
  IF jsonb_typeof(NEW.request_texts->n) IS DISTINCT FROM 'string' OR jsonb_typeof(NEW.row_texts->n) IS DISTINCT FROM 'string'
  THEN RAISE EXCEPTION 'CoreReview exact digest texts are required' USING ERRCODE='23514'; END IF;
  request_text:=NEW.request_texts->>n; rows_text:=NEW.row_texts->>n;
  IF encode(sha256(convert_to(request_text,'UTF8')),'hex') IS DISTINCT FROM b->>'request_hash'
  OR request_text::jsonb IS DISTINCT FROM c->'request'
  OR encode(sha256(convert_to(rows_text,'UTF8')),'hex') IS DISTINCT FROM b->>'rows_hash'
  THEN RAISE EXCEPTION 'CoreReview exact text digests differ' USING ERRCODE='23514'; END IF;
  SELECT * INTO STRICT p FROM public.catalog_file_import_previews WHERE tenant_id=NEW.tenant_id AND id=(b->>'preview_id')::uuid;
  IF p.actor_id IS DISTINCT FROM NEW.actor_id OR p.client_key IS DISTINCT FROM (b->>'preview_key')::uuid
  OR p.scope_hash IS DISTINCT FROM b->>'scope_hash' OR p.ready IS DISTINCT FROM true
  OR p.config IS DISTINCT FROM ((c->'request')-ARRAY['content','client_key'])
  OR p.source IS DISTINCT FROM (CASE WHEN NEW.api_key_id IS NULL THEN 'manual' ELSE 'api' END)
  OR (b#>'{preview,ack,head}') IS DISTINCT FROM jsonb_build_object('id',p.id,'actor_id',p.actor_id,'scope_hash',p.scope_hash,
    'total',p.total,'created',p.created,'updated',p.updated,'unchanged',p.unchanged,'invalid',p.invalid,'ready',p.ready,
    'created_at',b#>'{preview,ack,head,created_at}','config',p.config,'active_product_rules',jsonb_array_length(p.rules_snapshot))
  -- The existing HTTP pg Date projection is millisecond precision; preserve native UTC timestamp separately.
  OR jsonb_typeof(b#>'{preview,ack,head,created_at}') IS DISTINCT FROM 'string'
  OR (b#>>'{preview,ack,head,created_at}')::timestamptz IS DISTINCT FROM date_trunc('milliseconds',p.created_at)
  OR (SELECT count(*) FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id)<>p.total
  THEN RAISE EXCEPTION 'CoreReview actual native preview differs' USING ERRCODE='23514'; END IF;
  SELECT jsonb_agg((to_jsonb(x)-ARRAY['tenant_id','preview_id','byte_count'])||jsonb_build_object('changes',x.input) ORDER BY x.index)
  INTO actual_rows FROM public.catalog_file_import_rows x WHERE x.tenant_id=NEW.tenant_id AND x.preview_id=p.id;
  IF rows_text::jsonb IS DISTINCT FROM actual_rows
  OR (SELECT jsonb_agg(rr.v ORDER BY pg.page_ord,rr.ord)
    FROM jsonb_array_elements(c#>'{preview,pages}') WITH ORDINALITY pg(page_value,page_ord)
    CROSS JOIN LATERAL jsonb_array_elements(pg.page_value->'rows') WITH ORDINALITY rr(v,ord)) IS DISTINCT FROM actual_rows
  THEN RAISE EXCEPTION 'CoreReview digest text/full saved rows differ from native producer' USING ERRCODE='23514'; END IF;
  page_no:=0;count_rows:=0;
  FOR page IN SELECT value FROM jsonb_array_elements(b#>'{preview,pages}') LOOP
   IF public.large_import_core_review173_keys(page,ARRAY['head','rows','next','witness']) IS DISTINCT FROM true
   OR page->'head' IS DISTINCT FROM b#>'{preview,ack,head}' OR public.large_import_core_review173_ref(page->'witness') IS DISTINCT FROM true
   OR jsonb_typeof(page->'rows') IS DISTINCT FROM 'array' OR jsonb_array_length(page->'rows') NOT BETWEEN 1 AND 100
   THEN RAISE EXCEPTION 'CoreReview closed page differs' USING ERRCODE='23514'; END IF;
   FOR row_json IN SELECT value FROM jsonb_array_elements(page->'rows') LOOP
    SELECT * INTO STRICT nr FROM public.catalog_file_import_rows WHERE tenant_id=NEW.tenant_id AND preview_id=p.id AND index=count_rows;
    native_row:=(to_jsonb(nr)-ARRAY['tenant_id','preview_id','byte_count'])||jsonb_build_object('changes',nr.input);
    resolution:=b->'resolution'->count_rows;
    IF row_json IS DISTINCT FROM native_row OR nr.errors IS DISTINCT FROM '[]'::jsonb OR nr.operation NOT IN ('create','update','unchanged')
    OR nr.identity_value IS DISTINCT FROM c->'identities'->>count_rows
    OR public.large_import_core_review173_keys(resolution,ARRAY['ordinal','product_id','operation']) IS DISTINCT FROM true
    OR resolution->'ordinal' IS DISTINCT FROM to_jsonb(total_rows) OR nr.product_id IS NULL
    OR jsonb_typeof(resolution->'product_id') IS DISTINCT FROM 'string'
    OR (resolution->>'product_id') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
    OR (resolution->>'product_id')::uuid IS DISTINCT FROM nr.product_id
    OR resolution->>'operation' IS DISTINCT FROM nr.operation OR nr.product_id=ANY(ids)
    OR (nr.after->>'id')::uuid IS DISTINCT FROM nr.product_id OR jsonb_typeof(nr.after->'components') IS DISTINCT FROM 'array'
    THEN RAISE EXCEPTION 'CoreReview full native row/resolution differs' USING ERRCODE='23514'; END IF;
    ids:=array_append(ids,nr.product_id);batches:=array_append(batches,n);
    IF nr.after->>'parent_id' IS NOT NULL THEN links:=links||jsonb_build_array(jsonb_build_object('batch',n,'id',(nr.after->>'parent_id')::uuid)); END IF;
    FOR ref IN SELECT value FROM jsonb_array_elements(nr.after->'components') LOOP
     IF jsonb_typeof(ref->'product_id') IS DISTINCT FROM 'string' OR (ref->>'product_id') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
     THEN RAISE EXCEPTION 'CoreReview native component UUID is required' USING ERRCODE='23514'; END IF;
     links:=links||jsonb_build_array(jsonb_build_object('batch',n,'id',(ref->>'product_id')::uuid));
    END LOOP;
    count_rows:=count_rows+1;total_rows:=total_rows+1;
   END LOOP;
   IF page_no=jsonb_array_length(b#>'{preview,pages}')-1 THEN
    IF page->'next' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION 'CoreReview final cursor differs' USING ERRCODE='23514'; END IF;
   ELSIF page->'next' IS DISTINCT FROM to_jsonb(count_rows::text) OR count_rows>=p.total
   THEN RAISE EXCEPTION 'CoreReview intermediate cursor differs' USING ERRCODE='23514'; END IF;
   page_no:=page_no+1;
  END LOOP;
  IF count_rows<>p.total OR count_rows<>jsonb_array_length(c->'identities') OR count_rows<>jsonb_array_length(b->'resolution')
  THEN RAISE EXCEPTION 'CoreReview full batch count differs' USING ERRCODE='23514'; END IF;
  IF public.large_import_core_review173_keys(b->'eligibility',ARRAY['eligible','authority_revision','source_hash','sources','quota_witness']) IS DISTINCT FROM true
  OR jsonb_typeof(b#>'{eligibility,eligible}') IS DISTINCT FROM 'boolean'
  OR jsonb_typeof(b#>'{eligibility,authority_revision}') IS DISTINCT FROM 'string' OR length(b#>>'{eligibility,authority_revision}')=0
  OR jsonb_typeof(b#>'{eligibility,source_hash}') IS DISTINCT FROM 'string' OR (b#>>'{eligibility,source_hash}') !~ '^[a-f0-9]{64}$'
  OR jsonb_typeof(b#>'{eligibility,sources}') IS DISTINCT FROM 'array' OR jsonb_array_length(b#>'{eligibility,sources}')=0
  OR public.large_import_core_review173_ref(b#>'{eligibility,quota_witness}') IS DISTINCT FROM true
  THEN RAISE EXCEPTION 'CoreReview eligibility witness shape differs' USING ERRCODE='23514'; END IF;
  FOR ref IN SELECT value FROM jsonb_array_elements(b#>'{eligibility,sources}') LOOP
   IF public.large_import_core_review173_ref(ref) IS DISTINCT FROM true THEN RAISE EXCEPTION 'CoreReview source witness shape differs' USING ERRCODE='23514'; END IF;
  END LOOP;
  projected_batches:=projected_batches||jsonb_build_array(jsonb_build_object('index',n,'preview_id',b->'preview_id','scope_hash',b->'scope_hash',
    'preview_key',b->'preview_key','execute_key',b->'execute_key','request_hash',b->'request_hash','rows_hash',b->'rows_hash','resolution',b->'resolution',
    'source_hash',b#>'{eligibility,source_hash}','authority_revision',b#>'{eligibility,authority_revision}'));
  n:=n+1;
 END LOOP;
 IF total_rows<>(state#>>'{manifest,records}')::integer THEN RAISE EXCEPTION 'CoreReview whole record count differs' USING ERRCODE='23514'; END IF;
 FOR ref IN SELECT value FROM jsonb_array_elements(links) LOOP
  target:=(ref->>'id')::uuid;
  IF target=ANY(ids) AND batches[array_position(ids,target)]<>(ref->>'batch')::integer
  THEN RAISE EXCEPTION 'CoreReview cross-batch dependency requires separate plan' USING ERRCODE='23514'; END IF;
 END LOOP;
 projection:=jsonb_build_object('schema',r->'schema','source_plan_hash',r->'source_plan_hash','raw',r->'raw','parsing_spec',r->'parsing_spec','batches',projected_batches);
 IF NEW.scope_text::jsonb IS DISTINCT FROM projection
 THEN RAISE EXCEPTION 'CoreReview exact scope text business projection differs' USING ERRCODE='23514'; END IF;
 -- Only exact scope projection reaches this native serializer. Full request/rows are NEVER passed.
 canonical_scope:=public.large_import_core_scope173_text(projection);
 IF NEW.scope_text IS DISTINCT FROM canonical_scope
 OR NEW.aggregate_scope_hash IS DISTINCT FROM encode(sha256(convert_to(canonical_scope,'UTF8')),'hex')
 THEN RAISE EXCEPTION 'CoreReview scope native canonical bytes/hash differ' USING ERRCODE='23514'; END IF;
 IF NEW.approved_scope_hash IS NOT NULL AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'batches') AS approved_batch(value) WHERE approved_batch.value#>'{eligibility,eligible}' IS DISTINCT FROM 'true'::jsonb)
 THEN RAISE EXCEPTION 'CoreReview approval requires every eligibility witness true' USING ERRCODE='23514'; END IF;
 SELECT * INTO old_review FROM public.large_import_core_reviews173 WHERE tenant_id=NEW.tenant_id AND job_id=NEW.job_id ORDER BY revision DESC LIMIT 1;
 IF FOUND THEN
  -- A lost-COMMIT retry is a byte-identical no-op, not a second historical INSERT.
  IF (NEW.actor_id,NEW.api_key_id,NEW.revision,NEW.review_text,NEW.review_sha256,NEW.aggregate_scope_hash,NEW.approved_scope_hash,NEW.scope_text,NEW.request_texts,NEW.row_texts)
    IS NOT DISTINCT FROM (old_review.actor_id,old_review.api_key_id,old_review.revision,old_review.review_text,old_review.review_sha256,old_review.aggregate_scope_hash,old_review.approved_scope_hash,old_review.scope_text,old_review.request_texts,old_review.row_texts)
  THEN RETURN NULL; END IF;
  old_revision:=old_review.revision;
 ELSE
  old_revision:=-1;
  IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->'core') AS existing_core(value) WHERE existing_core.value ? 'execution')
  OR EXISTS(SELECT 1 FROM public.catalog_file_import_executions e WHERE e.tenant_id=NEW.tenant_id
    AND EXISTS(SELECT 1 FROM jsonb_array_elements(r->'batches') AS existing_batch(value) WHERE e.preview_id=(existing_batch.value->>'preview_id')::uuid))
  THEN RAISE EXCEPTION 'Initial CoreReview cannot follow a product execution' USING ERRCODE='23514'; END IF;
 END IF;
 IF NEW.revision<>old_revision+1 THEN RAISE EXCEPTION 'CoreReview append revision differs' USING ERRCODE='23514'; END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(state->'core') WITH ORDINALITY bc(v,i)
  WHERE NOT bc.v ? 'execution' AND EXISTS(SELECT 1 FROM jsonb_array_elements(state->'events') e WHERE e->>'kind'='core-execute-attempt' AND e->'batch'=to_jsonb((bc.i-1)::integer)))
 THEN RAISE EXCEPTION 'Unresolved original execution requires exact-key recovery' USING ERRCODE='23514'; END IF;
 -- Native canonical scope is enforced by the exact scoped serializer above. Native parity still requires Root PG gate.
 -- Full request/rows retain TEXT SHA + native business equality + strict JS bytes, no native whole-tree number serializer.
 -- Current Actor/session/IAM/source/quota admittance is still the genuine injected ports.admit / validateCoreBatch ABI;
 -- no such standalone native173 ABI is implemented/certified. Candidate activation is therefore NOT_APPLY_READY.
 -- A later composed current-admit/cert guard MUST close this external native-IAM trust boundary before activation.
 -- Missing ABI refuses deterministically; mere presence is NOT a certified IAM/call-context proof.
 -- Activation also requires owner-external certificate/preflight and a genuine same-transaction ports.admit.
 IF to_regprocedure('public.large_import173_admit(uuid,uuid,uuid,text,text,boolean)') IS NULL
 THEN RAISE EXCEPTION 'CoreReview current native admission ABI is absent' USING ERRCODE='0A000'; END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_core_scope173_json(v jsonb, depth integer DEFAULT 0)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE kind text:=jsonb_typeof(v); out text;n numeric;
BEGIN
 IF depth<0 OR depth>8 OR v IS NULL THEN RAISE EXCEPTION 'Scope canonical JSON depth/SQL-null differs' USING ERRCODE='23514';END IF;
 CASE kind
 WHEN 'null' THEN RETURN 'null';
 WHEN 'boolean' THEN RETURN CASE WHEN v='true'::jsonb THEN 'true' ELSE 'false' END;
 WHEN 'string' THEN RETURN public.large_import_core_scope173_quote(v#>>'{}');
 WHEN 'number' THEN
  n:=(v#>>'{}')::numeric;
  IF n<>trunc(n) OR abs(n)>9007199254740991 THEN RAISE EXCEPTION 'Only actual scope safe integers are serializable' USING ERRCODE='23514';END IF;
  -- JS JSON.stringify(-0)=0; scale/exponent spellings have no authority. No request/rows number reaches here.
  RETURN trunc(n)::text;
 WHEN 'array' THEN
  SELECT '['||coalesce(string_agg(public.large_import_core_scope173_json(value,depth+1),',' ORDER BY ord),'')||']' INTO out
  FROM jsonb_array_elements(v) WITH ORDINALITY x(value,ord);RETURN out;
 WHEN 'object' THEN
  SELECT '{'||coalesce(string_agg(public.large_import_core_scope173_quote(key)||':'||public.large_import_core_scope173_json(value,depth+1),','
    ORDER BY CASE WHEN public.large_import_core_scope173_index(key) IS NULL THEN 1 ELSE 0 END,
    public.large_import_core_scope173_index(key),public.large_import_core_scope173_utf16_key(key)),'')||'}' INTO out
  FROM jsonb_each(v);RETURN out;
 ELSE RAISE EXCEPTION 'Scope canonical JSON type differs' USING ERRCODE='23514';
 END CASE;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_core_scope173_text(scope jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE spec jsonb;b jsonb;r jsonb;k text;value jsonb;cap bigint;batch_no integer:=0;ordinal integer:=0;text_value text;
BEGIN
 IF getdatabaseencoding()<>'UTF8' THEN RAISE EXCEPTION 'Scope Unicode serialization requires UTF8 database' USING ERRCODE='0A000';END IF;
 -- These constraints match frozen Job Spec/Ref limits; they NEVER validate/narrow full request or rows.
 IF public.large_import_core_review173_keys(scope,ARRAY['schema','source_plan_hash','raw','parsing_spec','batches']) IS DISTINCT FROM true
 OR scope->>'schema' IS DISTINCT FROM 'large-import-core-review/v1'
 OR jsonb_typeof(scope->'source_plan_hash') IS DISTINCT FROM 'string' OR (scope->>'source_plan_hash') !~ '^[a-f0-9]{64}$'
 OR public.large_import_core_review173_keys(scope->'raw',ARRAY['id','sha256','byte_count']) IS DISTINCT FROM true
 OR jsonb_typeof(scope#>'{raw,id}') IS DISTINCT FROM 'string' OR length(scope#>>'{raw,id}')=0 OR octet_length(scope#>>'{raw,id}')>500
 OR jsonb_typeof(scope#>'{raw,sha256}') IS DISTINCT FROM 'string' OR (scope#>>'{raw,sha256}') !~ '^[a-f0-9]{64}$'
 OR jsonb_typeof(scope#>'{raw,byte_count}') IS DISTINCT FROM 'number'
 OR (scope#>>'{raw,byte_count}')::numeric<>trunc((scope#>>'{raw,byte_count}')::numeric)
 OR (scope#>>'{raw,byte_count}')::numeric NOT BETWEEN 0 AND 67108864
 OR jsonb_typeof(scope->'batches') IS DISTINCT FROM 'array' OR jsonb_array_length(scope->'batches') NOT BETWEEN 1 AND 100000
 THEN RAISE EXCEPTION 'Scope canonical projection shape differs' USING ERRCODE='23514';END IF;
 spec:=scope->'parsing_spec';
 IF spec->>'format'='csv' THEN
  IF jsonb_typeof(spec) IS DISTINCT FROM 'object' OR NOT(spec ?& ARRAY['format','delimiter'])
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(spec) AS object_keys(key_name) WHERE object_keys.key_name<>ALL(ARRAY['format','delimiter','limits']))
  OR jsonb_typeof(spec->'delimiter') IS DISTINCT FROM 'string' OR spec->>'delimiter' NOT IN (',',';',chr(9),'|')
  THEN RAISE EXCEPTION 'Scope CSV Spec differs' USING ERRCODE='23514';END IF;
 ELSE
  IF jsonb_typeof(spec) IS DISTINCT FROM 'object' OR spec->>'format' IS DISTINCT FROM 'xml' OR NOT(spec ?& ARRAY['format','recordPath'])
  OR EXISTS(SELECT 1 FROM jsonb_object_keys(spec) AS object_keys(key_name) WHERE object_keys.key_name<>ALL(ARRAY['format','recordPath','limits']))
  OR jsonb_typeof(spec->'recordPath') IS DISTINCT FROM 'string' OR length(spec->>'recordPath')=0
  OR octet_length(public.large_import_core_scope173_utf16_key(spec->>'recordPath'))/2>1024
  THEN RAISE EXCEPTION 'Scope XML Spec differs' USING ERRCODE='23514';END IF;
 END IF;
 IF spec ? 'limits' THEN
  IF jsonb_typeof(spec->'limits') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Scope limits differ' USING ERRCODE='23514';END IF;
  FOR k,value IN SELECT fields.key,fields.value FROM jsonb_each(spec->'limits') fields LOOP
   cap:=CASE k WHEN 'maxFileBytes' THEN 30000000 WHEN 'maxRecords' THEN 100000 WHEN 'batchRows' THEN 500 WHEN 'batchBytes' THEN 2097152
    WHEN 'maxRecordBytes' THEN 1048576 WHEN 'maxTokenBytes' THEN 1048576 WHEN 'maxColumns' THEN 1000 WHEN 'xmlDepth' THEN 16 WHEN 'xmlNodes' THEN 1000000 ELSE NULL END;
   IF cap IS NULL OR jsonb_typeof(value) IS DISTINCT FROM 'number' OR (value#>>'{}')::numeric<>trunc((value#>>'{}')::numeric)
   OR (value#>>'{}')::numeric NOT BETWEEN 1 AND cap THEN RAISE EXCEPTION 'Scope actual Spec limit differs' USING ERRCODE='23514';END IF;
  END LOOP;
 END IF;
 FOR b IN SELECT elements.value FROM jsonb_array_elements(scope->'batches') elements LOOP
  IF public.large_import_core_review173_keys(b,ARRAY['index','preview_id','scope_hash','preview_key','execute_key','request_hash','rows_hash','resolution','source_hash','authority_revision']) IS DISTINCT FROM true
  OR b->'index' IS DISTINCT FROM to_jsonb(batch_no)
  OR jsonb_typeof(b->'authority_revision') IS DISTINCT FROM 'string' OR length(b->>'authority_revision')=0
  OR jsonb_typeof(b->'resolution') IS DISTINCT FROM 'array' OR jsonb_array_length(b->'resolution') NOT BETWEEN 1 AND 500
  THEN RAISE EXCEPTION 'Scope batch projection differs' USING ERRCODE='23514';END IF;
  FOREACH k IN ARRAY ARRAY['scope_hash','request_hash','rows_hash','source_hash'] LOOP
   IF jsonb_typeof(b->k) IS DISTINCT FROM 'string' OR (b->>k) !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Scope hash scalar differs' USING ERRCODE='23514';END IF;
  END LOOP;
  FOREACH k IN ARRAY ARRAY['preview_id','preview_key','execute_key'] LOOP
   IF jsonb_typeof(b->k) IS DISTINCT FROM 'string' OR (b->>k) !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
   THEN RAISE EXCEPTION 'Scope UUID scalar differs' USING ERRCODE='23514';END IF;
  END LOOP;
  FOR r IN SELECT elements.value FROM jsonb_array_elements(b->'resolution') elements LOOP
   IF public.large_import_core_review173_keys(r,ARRAY['ordinal','product_id','operation']) IS DISTINCT FROM true OR r->'ordinal' IS DISTINCT FROM to_jsonb(ordinal)
   OR ordinal>=100000 OR jsonb_typeof(r->'product_id') IS DISTINCT FROM 'string' OR (r->>'product_id') !~* '^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$'
   OR jsonb_typeof(r->'operation') IS DISTINCT FROM 'string' OR r->>'operation' NOT IN ('create','update','unchanged')
   THEN RAISE EXCEPTION 'Scope resolution projection differs' USING ERRCODE='23514';END IF;
   ordinal:=ordinal+1;
  END LOOP;
  batch_no:=batch_no+1;
 END LOOP;
 text_value:=public.large_import_core_scope173_json(scope);
 IF octet_length(text_value)>67108864 THEN RAISE EXCEPTION 'Scope canonical text exceeds metadata bound' USING ERRCODE='54000';END IF;
 RETURN text_value;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_core_scope173_utf16_key(s text)
 RETURNS bytea
 LANGUAGE plpgsql
 IMMUTABLE STRICT
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE i integer; cp integer; out text:='';
BEGIN
 FOR i IN 1..char_length(s) LOOP
  cp:=ascii(substr(s,i,1));
  IF cp<65536 THEN out:=out||lpad(to_hex(cp),4,'0');
  ELSE cp:=cp-65536;out:=out||lpad(to_hex(55296+cp/1024),4,'0')||lpad(to_hex(56320+cp%1024),4,'0');END IF;
 END LOOP;
 RETURN decode(out,'hex');
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_absent_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE b record;old record;x record;policy_count integer;prefix0 text;paths0 text[];resources0 jsonb;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'Absent reconciliation requires READ COMMITTED' USING ERRCODE='25000';END IF;
 PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);
 PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:global',0));PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:tenant:'||t::text,0));
 PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN('global','tenant:'||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;
 IF policy_count<>2 THEN RAISE EXCEPTION 'Absent reconciliation quota policies missing' USING ERRCODE='55000';END IF;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;
 IF NOT FOUND OR b.kind IS DISTINCT FROM 'upload' OR client0 IS NULL THEN RAISE EXCEPTION 'Absent reconciliation upload not owned' USING ERRCODE='42501';END IF;
 IF b.state='retained' THEN
  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key='event:upload-absent-close:'||client0::text AND state='settled';
  IF NOT FOUND OR b.outcome IS DISTINCT FROM 'absent' OR old.payload_text::jsonb->'receipt'->>'client_key' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION 'Absent reconciliation original key conflict' USING ERRCODE='23505';END IF;
  RETURN jsonb_build_object('reused',true,'reservation',to_jsonb(b)-'token_hash','receipt',old.payload_text::jsonb->'receipt');
 END IF;
 IF b.state IS DISTINCT FROM 'unknown' THEN RAISE EXCEPTION 'Absent reconciliation requires committed unknown writer fence' USING ERRCODE='40001';END IF;
 -- UPDATE conflicts with every mandatory writer SHARE pin. A prior writer completes before this cut;
 -- strengthened publication_pin requires OPEN, so no later writer may publish while/after UNKNOWN.
 PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);
 prefix0:=t::text||'/'||u::text||'/'||CASE WHEN k IS NULL THEN 'sessions' ELSE 'key-'||k::text END;
 paths0:=ARRAY[t::text,t::text||'/'||u::text,prefix0,prefix0||'/uploads',prefix0||'/uploads/'||b.request_id::text];
 SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE "C"),'[]'::jsonb) INTO resources0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;
 IF jsonb_array_length(resources0)<>5 THEN RAISE EXCEPTION 'Absent reconciliation requires exact five-directory prefix' USING ERRCODE='23514';END IF;
 FOR x IN SELECT * FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q ORDER BY resource_key COLLATE "C" FOR UPDATE LOOP
  IF x.state IS DISTINCT FROM 'intent' OR x.kind IS DISTINCT FROM 'blob' OR x.payload_text IS NULL
  OR x.payload_text::jsonb->>'schema' IS DISTINCT FROM 'private-directory-allocation/v1'
  OR NOT ((x.payload_text::jsonb->>'path')=ANY(paths0))
  OR x.payload_text::jsonb IS DISTINCT FROM jsonb_build_object('schema','private-directory-allocation/v1','path',x.payload_text::jsonb->>'path','mode',448)
  OR x.resource_key IS DISTINCT FROM 'blob:fs:directory:'||encode(sha256(convert_to(x.payload_text::jsonb->>'path','UTF8')),'hex')
  OR x.byte_count IS DISTINCT FROM octet_length(x.payload_text)::bigint OR x.sha256 IS DISTINCT FROM encode(sha256(convert_to(x.payload_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'Absent reconciliation original directory allocation mismatch' USING ERRCODE='23514';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT z.payload_text::jsonb->>'path') FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q)<>5 THEN RAISE EXCEPTION 'Absent reconciliation duplicate paths' USING ERRCODE='23514';END IF;
 -- Conservative scope: this special prefix accepts no actor-owned blob/job/review metadata at all.
 -- Child parts/batches/events cannot exist without their FK parents. General failed uploads use a different keeper.
 IF EXISTS(SELECT 1 FROM public.large_import_blobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)
 OR EXISTS(SELECT 1 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k)
 OR EXISTS(SELECT 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k) THEN RAISE EXCEPTION 'Absent reconciliation has native upload/business metadata' USING ERRCODE='23514';END IF;
 RETURN jsonb_build_object('reused',false,'reservation',to_jsonb(b)-'token_hash','resources',resources0,'expected_paths',to_jsonb(paths0));
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_absent_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE fact jsonb;p jsonb;wanted jsonb;path0 jsonb;b record;receipt0 jsonb;evidence0 text;inventory0 text;key0 text;
BEGIN
 fact:=public.large_import_quota_absent_begin173(u,t,k,r,h,q,token,client0);IF fact->'reused'='true'::jsonb THEN RETURN fact;END IF;
 IF proof0 IS NULL OR octet_length(proof0)>1048576 THEN RAISE EXCEPTION 'Absent reconciliation bounded private proof required' USING ERRCODE='22023';END IF;
 p:=proof0::jsonb;
 SELECT coalesce(jsonb_agg(jsonb_build_object('resource_key',z->>'resource_key','kind',z->>'kind','byte_count',z->'byte_count','sha256',z->>'sha256','state',z->>'state','payload_text',z->>'payload_text') ORDER BY z->>'resource_key' COLLATE "C"),'[]'::jsonb) INTO wanted FROM jsonb_array_elements(fact->'resources') z;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p))<>7 OR p->>'schema' IS DISTINCT FROM 'private-upload-absent-close/v1'
 OR p->'scope' IS DISTINCT FROM jsonb_build_object('tenantId',t,'actorId',u,'apiKeyId',k) OR p->>'reservation_id' IS DISTINCT FROM q::text
 OR p->>'request_id' IS DISTINCT FROM fact->'reservation'->>'request_id' OR p->'resources' IS DISTINCT FROM wanted
 OR jsonb_typeof(p->'fs_cut') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'fs_cut')<>6
 OR p->'fs_cut'->0->>'path' IS DISTINCT FROM '.' OR p->'fs_cut'->0->>'state' IS DISTINCT FROM 'present'
 OR p->'fs_cut'->0->>'kind' IS DISTINCT FROM 'directory' OR p->'fs_cut'->0->>'mode' IS DISTINCT FROM '448'
 OR p->'metadata_cut' IS DISTINCT FROM jsonb_build_object('blobs',0,'jobs',0,'reviews',0) THEN RAISE EXCEPTION 'Absent reconciliation full original proof mismatch' USING ERRCODE='23514';END IF;
 FOR path0 IN SELECT value FROM jsonb_array_elements(fact->'expected_paths') LOOP
  IF (SELECT count(*) FROM jsonb_array_elements(p->'fs_cut') z WHERE z=jsonb_build_object('path',path0,'state','absent'))<>1 THEN RAISE EXCEPTION 'Absent reconciliation missing exact absent path' USING ERRCODE='23514';END IF;
 END LOOP;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;
 inventory0:=encode(sha256(convert_to(proof0,'UTF8')),'hex');receipt0:=jsonb_build_object('schema','quota-absent-close-receipt/v1','client_key',client0,'tenant_id',t,'reservation_id',q,'request_id',b.request_id,'inventory_sha256',inventory0,'released_directory_count',5,'native_time',clock_timestamp());
 evidence0:=jsonb_build_object('schema','quota-absent-close-evidence/v1','inventory_text',proof0,'receipt',receipt0)::text;key0:='event:upload-absent-close:'||client0::text;
 -- One retained metadata resource stores the immutable original cut and receipt. Original five byte counts/hashes/payloads never change.
 IF 2::numeric*octet_length(evidence0)>b.metadata_ceiling OR 2>b.objects_ceiling THEN RAISE EXCEPTION 'Absent reconciliation evidence exceeds original ceiling' USING ERRCODE='54000';END IF;
 INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,'event',octet_length(evidence0),encode(sha256(convert_to(evidence0,'UTF8')),'hex'),'settled',evidence0);
 UPDATE public.large_import_quota_resources173 SET state='released' WHERE tenant_id=t AND reservation_id=q AND resource_key<>key0;
 UPDATE public.large_import_quota_reservations173 SET state='retained',outcome='absent',raw_charge=0,metadata_charge=2::numeric*octet_length(evidence0),objects_charge=2,closed_at=clock_timestamp(),inventory_sha256=inventory0 WHERE tenant_id=t AND id=q RETURNING * INTO b;
 PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);
 RETURN jsonb_build_object('reused',false,'reservation',to_jsonb(b)-'token_hash','receipt',receipt0);
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_authorize173(u uuid, t uuid, k uuid, r text, h text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE policy_count integer;
BEGIN
 -- VOLATILE SPI queries need fresh statement snapshots after the global advisory wait.
 -- RR/serializable snapshots established by prior IAM reads cannot safely sum cross-tenant allocations.
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'Quota writes require READ COMMITTED' USING ERRCODE='25000';
 END IF;
 PERFORM public.large_import173_admit(u,t,k,r,h,true);
 -- Every allocation/final settlement uses this identical global -> tenant order, including cross-tenant calls.
 PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:global',0));
 PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:tenant:'||t::text,0));
 PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN('global','tenant:'||t::text) ORDER BY scope FOR SHARE;
 GET DIAGNOSTICS policy_count=ROW_COUNT;
 IF policy_count<>2 THEN
  RAISE EXCEPTION 'Quota inventory/policy unavailable' USING ERRCODE='55000';
 END IF;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_close173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, outcome0 text, inventory text, keys0 text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE b record;x record;actual_keys text[];
BEGIN
 PERFORM public.large_import_quota_authorize173(u,t,k,r,h);
 IF token IS NULL OR outcome0 IS NULL OR outcome0 NOT IN('ready','quarantined','unknown') THEN RAISE EXCEPTION 'Quota close shape' USING ERRCODE='22023';END IF;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Quota close not owned' USING ERRCODE='42501';END IF;
 IF outcome0='unknown' THEN
  IF b.state='retained' THEN RETURN to_jsonb(b)-'token_hash';END IF;
  UPDATE public.large_import_quota_reservations173 SET state='unknown' WHERE tenant_id=t AND id=q RETURNING * INTO b;RETURN to_jsonb(b)-'token_hash'; -- Ceiling never released by expiry, revocation, uncertain commit, pending file or unknown ACK.
 END IF;
 IF inventory IS NULL OR inventory !~ '^[a-f0-9]{64}$' OR keys0 IS NULL OR array_position(keys0,NULL) IS NOT NULL THEN RAISE EXCEPTION 'Complete private inventory required' USING ERRCODE='22023';END IF;
 SELECT coalesce(array_agg(resource_key ORDER BY resource_key COLLATE "C"),ARRAY[]::text[]) INTO actual_keys FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;
 -- Use a second explicit aggregate record; do not rely on row/text aliases or nullable checks.
 SELECT coalesce(sum(byte_count) FILTER(WHERE kind='raw' AND state<>'released'),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>'raw' AND state<>'released'),0) metadata_used,coalesce(sum(CASE WHEN state='released' THEN 0 WHEN kind='raw' THEN 1 ELSE 2 END),0) objects_used,count(*) FILTER(WHERE state='intent') pending INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;
 IF actual_keys IS DISTINCT FROM keys0 OR x.pending<>0 THEN RAISE EXCEPTION 'Quota incomplete resource inventory' USING ERRCODE='23514';END IF;
 IF b.state='retained' THEN
  IF b.outcome IS DISTINCT FROM outcome0 OR b.inventory_sha256 IS DISTINCT FROM inventory OR b.raw_charge IS DISTINCT FROM x.raw_used OR b.metadata_charge IS DISTINCT FROM x.metadata_used OR b.objects_charge IS DISTINCT FROM x.objects_used THEN RAISE EXCEPTION 'Quota close replay conflict' USING ERRCODE='23505';END IF;RETURN to_jsonb(b)-'token_hash';
 END IF;
 UPDATE public.large_import_quota_reservations173 SET state='retained',outcome=outcome0,raw_charge=x.raw_used,metadata_charge=x.metadata_used,objects_charge=x.objects_used,closed_at=clock_timestamp(),inventory_sha256=inventory WHERE tenant_id=t AND id=q RETURNING * INTO b;
 PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(b)-'token_hash';
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_intent173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, key0 text, kind0 text, n bigint, sha text, payload text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE b record;old record;x record;
BEGIN
 PERFORM public.large_import_quota_authorize173(u,t,k,r,h);
 IF token IS NULL OR key0 IS NULL OR length(key0) NOT BETWEEN 1 AND 200 OR kind0 IS NULL OR kind0 NOT IN('raw','blob','batch','job','review','event') OR key0 !~ '^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$' OR split_part(key0,':',1) IS DISTINCT FROM kind0 OR n IS NULL OR n<0 OR sha IS NULL OR sha !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Quota intent shape' USING ERRCODE='22023';END IF;
 IF (kind0='raw' AND payload IS NOT NULL) OR (kind0<>'raw' AND (payload IS NULL OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,'UTF8')),'hex') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION 'Quota exact metadata payload bytes' USING ERRCODE='23514';END IF;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Quota reservation not owned' USING ERRCODE='42501';END IF;
 SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;
 IF FOUND THEN
  IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION 'Quota resource replay conflict' USING ERRCODE='23505';END IF;
  IF old.state='released' THEN RAISE EXCEPTION 'Terminal allocation cannot authorize publication' USING ERRCODE='23505';END IF;
  IF old.state='settled' OR old.state='quarantined' THEN RETURN to_jsonb(old)-'token_hash';END IF;
  RAISE EXCEPTION 'Pending resource requires inspection, not duplicate write' USING ERRCODE='40001';
 END IF;
 IF b.state IS DISTINCT FROM 'open' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Quota lease expired; retained allocation requires reconciliation' USING ERRCODE='40001';END IF;
 SELECT coalesce(sum(byte_count) FILTER(WHERE kind='raw' AND state<>'released'),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>'raw' AND state<>'released'),0) metadata_used,coalesce(sum(CASE WHEN state='released' THEN 0 WHEN kind='raw' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;
 IF x.raw_used+(CASE WHEN kind0='raw' THEN n ELSE 0 END)>b.raw_ceiling OR x.metadata_used+(CASE WHEN kind0<>'raw' THEN n*2::numeric ELSE 0 END)>b.metadata_ceiling OR x.objects_used+(CASE WHEN kind0='raw' THEN 1 ELSE 2 END)>b.objects_ceiling THEN RAISE EXCEPTION 'Quota resource ceiling exhausted' USING ERRCODE='54000';END IF;
 INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,kind0,n,sha,'intent',payload) RETURNING * INTO old;
 PERFORM public.large_import173_admit(u,t,k,r,h,true);RETURN to_jsonb(old)-'token_hash';
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_intent_many173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE b record;old record;x record;v jsonb;key0 text;kind0 text;n bigint;sha text;payload text;seen text[]:=ARRAY[]::text[];result jsonb:='[]'::jsonb;new_raw numeric:=0;new_metadata numeric:=0;new_objects numeric:=0;new_count integer:=0;
BEGIN
 -- Same existing READ COMMITTED/full currentIAM/global -> tenant -> policy order.
 PERFORM public.large_import_quota_authorize173(u,t,k,r,h);
 IF q IS NULL OR token IS NULL OR token !~ '^[a-f0-9]{64}$' OR items IS NULL OR jsonb_typeof(items) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Quota group shape' USING ERRCODE='22023';END IF;
 IF jsonb_array_length(items) NOT BETWEEN 1 AND 64 OR octet_length(items::text)>8388608 THEN RAISE EXCEPTION 'Quota group bound' USING ERRCODE='22023';END IF;
 -- Validate ALL shapes before reservation/resource mutation. Text payload is compared exactly,
 -- never JSON-projected or normalized; caller bytes/hash include original UTF8 serialization.
 FOR v IN SELECT value FROM jsonb_array_elements(items) LOOP
  IF jsonb_typeof(v) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(v) key) IS DISTINCT FROM ARRAY['byte_count','key','kind','payload_text','sha256']::text[] OR jsonb_typeof(v->'key') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'kind') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'sha256') IS DISTINCT FROM 'string' OR jsonb_typeof(v->'byte_count') IS DISTINCT FROM 'number' OR (v->>'byte_count') !~ '^(0|[1-9][0-9]{0,15})$' THEN RAISE EXCEPTION 'Quota group item shape' USING ERRCODE='22023';END IF;
  key0:=v->>'key';kind0:=v->>'kind';n:=(v->>'byte_count')::bigint;sha:=v->>'sha256';payload:=v->>'payload_text';
  IF key0 !~ '^(raw|blob|batch|job|review|event):[a-z0-9:-]{1,160}$' OR kind0 NOT IN('raw','blob','batch','job','review','event') OR split_part(key0,':',1) IS DISTINCT FROM kind0 OR sha !~ '^[a-f0-9]{64}$' OR n>9007199254740991 OR key0=ANY(seen) THEN RAISE EXCEPTION 'Quota group item identity' USING ERRCODE='22023';END IF;
  IF (kind0='raw' AND jsonb_typeof(v->'payload_text') IS DISTINCT FROM 'null') OR (kind0<>'raw' AND (jsonb_typeof(v->'payload_text') IS DISTINCT FROM 'string' OR octet_length(payload) IS DISTINCT FROM n OR encode(sha256(convert_to(payload,'UTF8')),'hex') IS DISTINCT FROM sha)) THEN RAISE EXCEPTION 'Quota group exact payload' USING ERRCODE='23514';END IF;
  seen:=array_append(seen,key0);
 END LOOP;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Quota group reservation not owned' USING ERRCODE='42501';END IF;
 -- Lock complete existing group in C byte order before any insertion. Reservation UPDATE also
 -- fences competing inserts under the unchanged native global lock protocol.
 PERFORM 1 FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=ANY(seen) ORDER BY resource_key COLLATE "C" FOR UPDATE;
 FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>'key') COLLATE "C" LOOP
  key0:=v->>'key';kind0:=v->>'kind';n:=(v->>'byte_count')::bigint;sha:=v->>'sha256';payload:=v->>'payload_text';
  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;
  IF FOUND THEN
   IF old.kind IS DISTINCT FROM kind0 OR old.byte_count IS DISTINCT FROM n OR old.sha256 IS DISTINCT FROM sha OR old.payload_text IS DISTINCT FROM payload THEN RAISE EXCEPTION 'Quota group replay conflict' USING ERRCODE='23505';END IF;
   IF old.state='released' THEN RAISE EXCEPTION 'Terminal allocation cannot authorize publication' USING ERRCODE='23505';END IF;
   IF old.state NOT IN('settled','quarantined') THEN RAISE EXCEPTION 'Pending resource requires inspection' USING ERRCODE='40001';END IF;
  ELSE
   IF b.state IS DISTINCT FROM 'open' OR b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Quota group lease unavailable' USING ERRCODE='40001';END IF;
   new_count:=new_count+1;new_raw:=new_raw+(CASE WHEN kind0='raw' THEN n ELSE 0 END);new_metadata:=new_metadata+(CASE WHEN kind0<>'raw' THEN n*2::numeric ELSE 0 END);new_objects:=new_objects+(CASE WHEN kind0='raw' THEN 1 ELSE 2 END);
  END IF;
 END LOOP;
 IF new_count>0 THEN
 SELECT coalesce(sum(byte_count) FILTER(WHERE kind='raw' AND state<>'released'),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>'raw' AND state<>'released'),0) metadata_used,coalesce(sum(CASE WHEN state='released' THEN 0 WHEN kind='raw' THEN 1 ELSE 2 END),0) objects_used INTO x FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;
 IF x.raw_used+new_raw>b.raw_ceiling OR x.metadata_used+new_metadata>b.metadata_ceiling OR x.objects_used+new_objects>b.objects_ceiling THEN RAISE EXCEPTION 'Quota group ceiling exhausted' USING ERRCODE='54000';END IF;
 END IF;
 FOR v IN SELECT value FROM jsonb_array_elements(items) ORDER BY (value->>'key') COLLATE "C" LOOP
  key0:=v->>'key';SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key=key0;
  IF NOT FOUND THEN INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,v->>'kind',(v->>'byte_count')::bigint,v->>'sha256','intent',v->>'payload_text') RETURNING * INTO old;END IF;
  result:=result||jsonb_build_array(to_jsonb(old));
 END LOOP;
 -- No saved verdict: complete graph + locked currentIAM again, after group effects. An elapsed
 -- new-write deadline rolls back the entire group. Exact settled replay never extends expiry.
 PERFORM public.large_import173_admit(u,t,k,r,h,true);
 IF new_count>0 AND b.expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'Quota group deadline elapsed' USING ERRCODE='40001';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_keeper_admit173(u uuid, t uuid, k uuid, r text, h text, w boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x record;v_now timestamptz;
BEGIN
 -- Schema fence FIRST; every original owner/IAM/late-clock predicate remains fresh.
 PERFORM public.ordinary182_require_generation();
 IF u IS NULL OR t IS NULL OR r IS NULL OR r NOT IN('admin','operator','viewer') OR h IS NULL OR h !~ '^[a-f0-9]{64}$' OR w IS NULL THEN
  RAISE EXCEPTION 'Invalid metadata authority' USING ERRCODE='42501';
 END IF;
 -- SD current_user is the module owner. The caller is a fresh, private dedicated owner keeper connection with role NONE; no role reset.
 IF current_setting('role',true) IS DISTINCT FROM 'none'
 OR session_user IS DISTINCT FROM pg_get_userbyid((SELECT relowner FROM pg_class WHERE oid=to_regclass('public.large_import173_certificate')))
 OR t IS DISTINCT FROM nullif(current_setting('app.tenant_id',true),'')::uuid THEN
  RAISE EXCEPTION 'Private keeper owner-role tenant transport mismatch' USING ERRCODE='42501';
 END IF;
 -- Owner startup MUST independently pin the complete current body/catalog graph before invoking the private keeper ABI.
 -- This leaf check alone is not self-attestation. The new helper+grant must be in that compiled certificate graph.

 -- Same order as native170 pin path; independent authority, without its lifecycle.
 -- Actual metadata checkpoint caller must be inside BEGIN; locks then survive through its COMMIT/ROLLBACK.
 PERFORM 1 FROM public.users WHERE id=u FOR SHARE;
 PERFORM 1 FROM public.tenants WHERE id=t FOR SHARE;
 PERFORM 1 FROM public.account_security WHERE user_id=u FOR SHARE;
 PERFORM 1 FROM public.workspace_security_policies WHERE tenant_id=t FOR SHARE;
 PERFORM 1 FROM public.memberships WHERE(user_id,tenant_id)=(u,t) FOR SHARE;
 IF k IS NULL THEN
  PERFORM 1 FROM public.sessions WHERE(token_hash,user_id,tenant_id)=(h,u,t) FOR SHARE;
 ELSE
  PERFORM 1 FROM public.api_keys WHERE(id,user_id,tenant_id)=(k,u,t) FOR SHARE;
 END IF;
 v_now:=clock_timestamp();
 IF k IS NULL THEN
  SELECT m.role,coalesce(a.version,0)::text account_version,true scope_ok,
   least(s.expires_at,CASE WHEN coalesce(p.require_mfa,false) THEN s.mfa_verified_at+interval '8 hours' ELSE s.expires_at END) deadline,
   coalesce(p.require_mfa,false) AND NOT(coalesce(a.enabled_at IS NOT NULL AND s.mfa_verified_at IS NOT NULL AND s.mfa_verified_at>v_now-interval '8 hours',false)) mfa_required INTO x
  FROM public.sessions s JOIN public.users z ON z.id=s.user_id JOIN public.tenants n ON n.id=s.tenant_id
  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)
  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id
  WHERE(s.token_hash,s.user_id,s.tenant_id)=(h,u,t) AND s.expires_at>v_now AND s.account_version=coalesce(a.version,0);
 ELSE
  SELECT m.role,coalesce(a.version,0)::text account_version,k0.expires_at deadline,
   k0.scopes@>CASE WHEN w THEN ARRAY['products:read','products:write']::text[] ELSE ARRAY['products:read']::text[] END scope_ok,
   coalesce(p.require_mfa,false) AND a.enabled_at IS NULL mfa_required INTO x
  FROM public.api_keys k0 JOIN public.users z ON z.id=k0.user_id JOIN public.tenants n ON n.id=k0.tenant_id
  JOIN public.memberships m ON(m.user_id,m.tenant_id)=(z.id,n.id)
  LEFT JOIN public.account_security a ON a.user_id=z.id LEFT JOIN public.workspace_security_policies p ON p.tenant_id=n.id
  WHERE(k0.id,k0.token_hash,k0.user_id,k0.tenant_id)=(k,h,u,t) AND k0.revoked_at IS NULL AND k0.expires_at>v_now;
 END IF;
 IF x.role IS NULL OR x.deadline IS NULL OR NOT isfinite(x.deadline) OR x.deadline<=clock_timestamp() THEN
  RAISE EXCEPTION 'Expired metadata authority' USING ERRCODE='28000';
 END IF;
 IF x.role<>r THEN RAISE EXCEPTION 'Metadata role changed' USING ERRCODE='40001';END IF;
 IF NOT coalesce(x.scope_ok,false) OR coalesce(x.mfa_required,true) OR(w AND x.role<>'admin') THEN
  RAISE EXCEPTION 'Missing current metadata authority' USING ERRCODE='42501';
 END IF;
END
$function$

CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_begin173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE b record;policy_count integer;old record;snapshot0 jsonb;
BEGIN
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN RAISE EXCEPTION 'Terminal writes require READ COMMITTED' USING ERRCODE='25000';END IF;
 PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);
 PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:global',0));PERFORM pg_advisory_xact_lock(hashtextextended('large-import173:quota:tenant:'||t::text,0));
 PERFORM 1 FROM public.large_import_quota_policies173 WHERE scope IN('global','tenant:'||t::text) ORDER BY scope FOR SHARE;GET DIAGNOSTICS policy_count=ROW_COUNT;
 IF policy_count<>2 THEN RAISE EXCEPTION 'Terminal quota policy absent' USING ERRCODE='55000';END IF;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND token_hash=token FOR UPDATE;
 IF NOT FOUND OR b.kind NOT IN('job','review') OR client0 IS NULL THEN RAISE EXCEPTION 'Known-close business request not owned' USING ERRCODE='42501';END IF;
 IF b.state='retained' THEN
  SELECT * INTO old FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q AND resource_key='event:business-known-close:'||client0::text AND state='settled';
  IF NOT FOUND OR b.outcome<>'ready' OR old.payload_text::jsonb->'receipt'->>'client_key' IS DISTINCT FROM client0::text THEN RAISE EXCEPTION 'Known-close original key conflict' USING ERRCODE='23505';END IF;
  RETURN jsonb_build_object('reused',true,'reservation',to_jsonb(b)-'token_hash','receipt',old.payload_text::jsonb->'receipt'); -- no fresh cut or callback on exact old-key recovery
 END IF;
 PERFORM public.large_import_quota_keeper_admit173(u,t,k,r,h,true);
 SELECT coalesce(jsonb_agg(to_jsonb(z) ORDER BY resource_key COLLATE "C"),'[]'::jsonb) INTO snapshot0 FROM public.large_import_quota_resources173 z WHERE tenant_id=t AND reservation_id=q;
 IF jsonb_array_length(snapshot0)=0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot0) x WHERE x->>'state' NOT IN('settled','released')) THEN RAISE EXCEPTION 'Known close has pending original allocations' USING ERRCODE='40001';END IF;
 RETURN jsonb_build_object('reused',false,'reservation',to_jsonb(b)-'token_hash','resources',snapshot0);
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_owned_close_finish173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text, client0 uuid, proof0 text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE fact jsonb;p jsonb;wanted jsonb;b record;job0 record;actual0 jsonb;charges record;receipt0 jsonb;evidence0 text;key0 text;inventory0 text;
BEGIN
 fact:=public.large_import_quota_owned_close_begin173(u,t,k,r,h,q,token,client0);IF fact->'reused'='true'::jsonb THEN RETURN fact;END IF;
 IF proof0 IS NULL OR octet_length(proof0)>8388608 THEN RAISE EXCEPTION 'Known-close bounded private proof required' USING ERRCODE='22023';END IF;
 p:=proof0::jsonb;
 SELECT coalesce(jsonb_agg(jsonb_build_object('resource_key',z->>'resource_key','kind',z->>'kind','byte_count',z->'byte_count','sha256',z->>'sha256','state',z->>'state') ORDER BY z->>'resource_key' COLLATE "C"),'[]'::jsonb) INTO wanted FROM jsonb_array_elements(fact->'resources') z;
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR (SELECT count(*) FROM jsonb_object_keys(p))<>9 OR p->>'schema' IS DISTINCT FROM 'private-business-known-close/v1'
 OR p->'scope' IS DISTINCT FROM jsonb_build_object('tenantId',t,'actorId',u,'apiKeyId',k) OR p->>'reservation_id' IS DISTINCT FROM q::text
 OR p->>'request_id' IS DISTINCT FROM fact->'reservation'->>'request_id' OR p->'resources' IS DISTINCT FROM wanted
 OR p->>'kind' IS DISTINCT FROM fact->'reservation'->>'kind' OR jsonb_typeof(p->'fs_cut') IS DISTINCT FROM 'array'
 OR jsonb_typeof(p->'metadata_cut') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Known-close full original inventory mismatch' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT 1 FROM public.large_import_quota_resources173 z WHERE z.tenant_id=t AND z.reservation_id=q AND z.state='released' AND NOT EXISTS(SELECT 1 FROM public.large_import_quota_terminal_receipts173 e WHERE(e.tenant_id,e.reservation_id,e.resource_key)=(z.tenant_id,z.reservation_id,z.resource_key))) THEN RAISE EXCEPTION 'Released allocation lacks immutable native receipt' USING ERRCODE='23514';END IF;
 SELECT * INTO job0 FROM public.large_import_jobs173 WHERE tenant_id=t AND actor_id=u AND api_key_id IS NOT DISTINCT FROM k AND id=(p->>'job_id')::uuid FOR SHARE;
 IF NOT FOUND OR job0.lease_token IS NOT NULL OR job0.leased_at IS NOT NULL THEN RAISE EXCEPTION 'Business job is not owned/quiescent' USING ERRCODE='40001';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(job0.state_text::jsonb->'core') batch WHERE jsonb_typeof(batch->'execution') IS DISTINCT FROM 'object')
 OR EXISTS(SELECT 1 FROM jsonb_each(job0.state_text::jsonb->'pim') group0 CROSS JOIN LATERAL jsonb_array_elements(group0.value) attempt WHERE ((attempt->>'applyAttempted')::boolean AND jsonb_typeof(attempt->'applied') IS DISTINCT FROM 'object') OR ((attempt->>'previewAttempted')::boolean AND jsonb_typeof(attempt->'preview') IS DISTINCT FROM 'object'))
 THEN RAISE EXCEPTION 'Unresolved original business outcome' USING ERRCODE='40001';END IF;
 PERFORM 1 FROM public.large_import_events173 WHERE tenant_id=t AND job_id=job0.id ORDER BY sequence FOR SHARE;
 PERFORM 1 FROM public.large_import_core_reviews173 WHERE tenant_id=t AND job_id=job0.id ORDER BY revision FOR SHARE;
 SELECT jsonb_build_object('job',jsonb_build_object('state_text',job0.state_text,'state_sha256',job0.state_sha256,'revision',job0.revision,'lease_fence',job0.lease_fence::text,'lease_token',job0.lease_token,'leased_at',job0.leased_at),
 'events',(SELECT coalesce(jsonb_agg(jsonb_build_object('sequence',e.sequence,'revision',e.revision,'event_text',e.event_text,'event_sha256',e.event_sha256) ORDER BY e.sequence),'[]'::jsonb) FROM public.large_import_events173 e WHERE e.tenant_id=t AND e.job_id=job0.id),
 'reviews',(SELECT coalesce(jsonb_agg(jsonb_build_object('revision',v.revision,'review_text',v.review_text,'review_sha256',v.review_sha256,'job_revision',v.job_revision,'lease_fence',v.lease_fence::text,'scope_text',v.scope_text,'request_texts',v.request_texts,'row_texts',v.row_texts) ORDER BY v.revision),'[]'::jsonb) FROM public.large_import_core_reviews173 v WHERE v.tenant_id=t AND v.job_id=job0.id)) INTO actual0;
 IF p->'metadata_cut' IS DISTINCT FROM actual0 THEN RAISE EXCEPTION 'Business native metadata cut mismatch' USING ERRCODE='23514';END IF;
 SELECT * INTO b FROM public.large_import_quota_reservations173 WHERE tenant_id=t AND id=q;
