 evidence0:=jsonb_build_object('schema','quota-known-close-evidence/v1','inventory_text',proof0,'receipt',receipt0)::text;key0:='event:business-known-close:'||client0::text;
 IF octet_length(evidence0)>8388608 THEN RAISE EXCEPTION 'Known-close evidence limit' USING ERRCODE='54000';END IF;
 SELECT coalesce(sum(byte_count) FILTER(WHERE kind='raw' AND state<>'released'),0) raw_used,coalesce(sum(byte_count*2::numeric) FILTER(WHERE kind<>'raw' AND state<>'released'),0) metadata_used,coalesce(sum(CASE WHEN state='released' THEN 0 WHEN kind='raw' THEN 1 ELSE 2 END),0) objects_used INTO charges FROM public.large_import_quota_resources173 WHERE tenant_id=t AND reservation_id=q;
 IF charges.raw_used>b.raw_ceiling OR charges.metadata_used+2::numeric*octet_length(evidence0)>b.metadata_ceiling OR charges.objects_used+2>b.objects_ceiling THEN RAISE EXCEPTION 'Known-close evidence exceeds original ceiling' USING ERRCODE='54000';END IF;
 INSERT INTO public.large_import_quota_resources173 VALUES(t,q,key0,'event',octet_length(evidence0),encode(sha256(convert_to(evidence0,'UTF8')),'hex'),'settled',evidence0);
