  -- Deliberately retains old settle173 DML semantics even for identical-state replay.
  UPDATE public.large_import_quota_resources173 SET state=v->>'state' WHERE tenant_id=t AND reservation_id=q AND resource_key=v->>'key' RETURNING * INTO x;
  result:=result||jsonb_build_array(to_jsonb(x));
 END LOOP;
 PERFORM public.large_import173_admit(u,t,k,r,h,true);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION public.large_import_quota_snapshot173(u uuid, t uuid, k uuid, r text, h text, q uuid, token text)
