warehouse_wz_issuer_guards.definition:
CREATE OR REPLACE FUNCTION public.warehouse_wz_issuer_guards()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE expected text;BEGIN
 IF NOT public.warehouse_wz_issuer_installed() THEN RETURN false;END IF;
 IF to_regprocedure('public.warehouse_automatic_wz_guards()') IS NULL OR NOT public.warehouse_automatic_wz_guards() THEN RETURN false;END IF;
 IF(SELECT count(*) FROM pg_trigger t JOIN pg_class c ON c.oid=t.tgrelid WHERE c.relnamespace='public'::regnamespace AND c.relname=ANY(ARRAY['orders','order_items','shipments','reservations','reservation_locations','stock','stock_locations','wms_reservation_layers','wms_layer_positions','stock_movements','stock_location_movements','wms_operations','wms_issue_fragments','wms_layer_movements'])
  AND t.tgname='warehouse_wz_issuer_source_seal' AND t.tgfoid='public.warehouse_wz_issuer_source_seal()'::regprocedure AND t.tgtype=31 AND t.tgenabled='O' AND NOT t.tgisinternal AND t.tgqual IS NULL AND t.tgargs='\x'::bytea AND t.tgattr::text='')<>14 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM pg_class c CROSS JOIN LATERAL aclexplode(coalesce(c.relacl,acldefault('r',c.relowner))) a WHERE c.relnamespace='public'::regnamespace AND c.relkind='r' AND c.relname LIKE 'warehouse_wz_issuer_%' AND a.grantee<>c.relowner)
  OR EXISTS(SELECT 1 FROM pg_class c JOIN pg_attribute b ON b.attrelid=c.oid CROSS JOIN LATERAL aclexplode(b.attacl) a WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'warehouse_wz_issuer_%' AND a.grantee<>c.relowner)
  OR EXISTS(SELECT 1 FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'warehouse_wz_issuer_%' AND a.grantee<>p.proowner) THEN RETURN false;END IF;
 SELECT fingerprint INTO expected FROM public.warehouse_wz_issuer_manifest WHERE singleton;
 RETURN expected IS NOT NULL AND public.parcel_physical_wz_valid();
EXCEPTION WHEN undefined_table OR undefined_function OR undefined_column THEN RETURN false;
END $function$

catalog_stock_return_guards.definition:
CREATE OR REPLACE FUNCTION public.catalog_stock_return_guards()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ownerid oid:=(SELECT proowner FROM pg_proc WHERE oid='public.catalog_stock_return_guards()'::regprocedure);
BEGIN
 -- Separate statement avoids planning a call to an absent optional phase delegate.
 IF to_regprocedure('public.catalog_stock_legacy_group_guards()') IS NULL THEN RETURN false;END IF;
 IF NOT public.catalog_stock_control_installed() OR NOT public.catalog_stock_legacy_group_guards() OR
  (SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'catalog_stock_return_%' AND relkind='r')<>8 THEN RETURN false;END IF;
 IF EXISTS(SELECT FROM pg_class c WHERE c.relnamespace='public'::regnamespace AND c.relname LIKE 'catalog_stock_return_%' AND c.relkind='r' AND
  (c.relowner<>ownerid OR NOT c.relrowsecurity OR NOT c.relforcerowsecurity OR EXISTS(SELECT FROM aclexplode(coalesce(c.relacl,acldefault('r',c.relowner)))a WHERE a.grantee<>ownerid) OR
   EXISTS(SELECT FROM pg_attribute x CROSS JOIN LATERAL aclexplode(x.attacl)a WHERE x.attrelid=c.oid AND a.grantee<>ownerid))) OR
  EXISTS(SELECT FROM pg_proc p WHERE p.pronamespace='public'::regnamespace AND p.proname LIKE 'catalog_stock_return_%' AND
   (p.proowner<>ownerid OR NOT p.prosecdef OR EXISTS(SELECT FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner)))a WHERE a.grantee<>ownerid))) THEN RETURN false;END IF;
 -- The parent manifest pins the complete implementations of both delegates;
 -- this non-recursive guard also checks their installed, explicit wiring.
 IF to_regprocedure('public.catalog_stock_control_effect_validate(uuid)') IS NULL OR
    to_regprocedure('public.catalog_stock_control_counter_complete()') IS NULL THEN RETURN false;END IF;
 IF position('PERFORM public.catalog_stock_return_validate(eid);' IN(SELECT prosrc FROM pg_proc WHERE oid='public.catalog_stock_control_effect_validate(uuid)'::regprocedure))=0 OR
    position('FROM public.catalog_stock_return_documents WHERE(tenant_id,series_id,year)=(NEW.tenant_id,NEW.series_id,NEW.year)' IN(SELECT prosrc FROM pg_proc WHERE oid='public.catalog_stock_control_counter_complete()'::regprocedure))=0 THEN RETURN false;END IF;
 RETURN coalesce((SELECT fingerprint=public.catalog_stock_return_fingerprint() FROM public.catalog_stock_return_manifest WHERE id),false);
END $function$

credit_source_upgrade_valid.definition:
CREATE OR REPLACE FUNCTION public.credit_source_upgrade_valid()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE c record;tab text;sig text;BEGIN
 IF EXISTS(SELECT FROM pg_class WHERE relnamespace='public'::regnamespace AND starts_with(relname,'financial_return_'))
 OR EXISTS(SELECT FROM pg_proc WHERE pronamespace='public'::regnamespace AND starts_with(proname,'financial_return_'))
 OR EXISTS(SELECT FROM pg_trigger WHERE starts_with(tgname,'financial_return_'))
 OR EXISTS(SELECT FROM migrations WHERE name='162_financial_return') THEN
  IF to_regprocedure('public.financial_return_upgrade_valid()') IS NULL THEN RETURN false;END IF;
  RETURN financial_return_upgrade_valid();
 END IF;
 IF current_setting('session_replication_role')<>'origin' THEN RETURN false;END IF;
 FOREACH tab IN ARRAY ARRAY['migrations','local_invoice_manifest','fa3_draft_manifest','b2b_invoice_upgrade','b2b_credit_upgrade','credit_source_upgrade_certificate'] LOOP IF to_regclass('public.'||tab) IS NULL THEN RETURN false;END IF;END LOOP;
 FOREACH sig IN ARRAY ARRAY['local_invoice_fingerprint()','fa3_draft_fingerprint()','b2b_invoice_fingerprint()','b2b_credit_fingerprint()','b2b_credit_basis(uuid,uuid)','b2b_credit_upgrade_valid()','credit_source_upgrade_context()','credit_source_upgrade_fingerprint()','credit_source_upgrade_valid()','credit_source_upgrade_guard()'] LOOP IF to_regprocedure('public.'||sig) IS NULL THEN RETURN false;END IF;END LOOP;
 IF to_regclass('public.document_order_mode') IS NULL OR to_regclass('public.document_return_mode') IS NULL THEN RETURN false;END IF;
 IF(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'credit\_source\_upgrade\_%' ESCAPE '\')<>2
 OR EXISTS(SELECT FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'credit\_source\_upgrade\_%' ESCAPE '\' AND NOT((relname='credit_source_upgrade_certificate' AND relkind='r') OR(relname='credit_source_upgrade_certificate_pkey' AND relkind='i')))
 OR(SELECT count(*) FROM pg_class WHERE relnamespace='public'::regnamespace AND relname LIKE 'credit\_source\_upgrade\_%' ESCAPE '\' AND relkind IN('r','p'))<>1
 OR NOT EXISTS(SELECT FROM pg_class WHERE oid='public.credit_source_upgrade_certificate'::regclass AND relkind='r' AND relrowsecurity AND relforcerowsecurity)
 OR(SELECT count(*) FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname LIKE 'credit\_source\_upgrade\_%' ESCAPE '\')<>4
 OR(SELECT count(*) FROM pg_trigger WHERE tgname LIKE 'credit\_source\_upgrade\_%' ESCAPE '\')<>1
 OR NOT EXISTS(SELECT FROM pg_trigger WHERE tgname='credit_source_upgrade_guard' AND tgrelid='public.credit_source_upgrade_certificate'::regclass AND tgfoid='public.credit_source_upgrade_guard()'::regprocedure AND NOT tgisinternal AND tgenabled='O' AND NOT tgdeferrable) THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM migrations WHERE name='160_b2b_credit') OR(SELECT count(*) FROM credit_source_upgrade_certificate)<>1
 OR(SELECT count(*) FROM local_invoice_manifest)<>1 OR(SELECT count(*) FROM fa3_draft_manifest)<>1 OR(SELECT count(*) FROM b2b_invoice_upgrade)<>1 OR(SELECT count(*) FROM b2b_credit_upgrade)<>1 THEN RETURN false;END IF;
 IF NOT EXISTS(SELECT FROM migrations WHERE name='161_credit_source') AND NOT credit_source_upgrade_context() THEN RETURN false;END IF;
 SELECT * INTO c FROM credit_source_upgrade_certificate WHERE id;
 RETURN coalesce(c.profile='160-original-to161-empty-source/v1'
 AND c.original=jsonb_build_object('157',(SELECT to_jsonb(m) FROM local_invoice_manifest m WHERE id),'158',(SELECT to_jsonb(m) FROM fa3_draft_manifest m WHERE id),'159',(SELECT to_jsonb(m) FROM b2b_invoice_upgrade m WHERE id),'160',(SELECT to_jsonb(m) FROM b2b_credit_upgrade m WHERE id))
 AND c.predecessors=jsonb_build_object('157',c.original#>>'{160,successor157}','158',c.original#>>'{160,successor158}','159',c.original#>>'{160,successor159}','160',c.original#>>'{160,successor160}')
 AND c.successors->>'157'=c.predecessors->>'157'
 AND c.successors=jsonb_build_object('157',local_invoice_fingerprint(),'158',fa3_draft_fingerprint(),'159',b2b_invoice_fingerprint(),'160',b2b_credit_fingerprint(),'161',credit_source_upgrade_fingerprint())
 AND jsonb_array_length(c.replaced_functions)=2
 AND(c.original#>'{160,original157}')=c.original->'157' AND(c.original#>'{160,original158}')=c.original->'158' AND(c.original#>'{160,original159}')=c.original->'159'
 AND c.original#>'{160,original014_indexes}'=(SELECT jsonb_agg(pg_get_indexdef(i.indexrelid) ORDER BY i.indexrelid::regclass::text) FROM pg_index i WHERE i.indexrelid IN('public.document_order_mode'::regclass,'public.document_return_mode'::regclass)),false);
END$function$

