DECLARE e ordinary187_private.journal%ROWTYPE;m ordinary187_private.journal%ROWTYPE;b jsonb;
BEGIN
 PERFORM public.ordinary187_owner_context();SELECT * INTO STRICT e FROM ordinary187_private.journal WHERE root_key=root0 AND epoch=epoch0 AND kind='epoch';
 -- Preallocated no-growth xid journal MUST NOT join a row-lock queue behind POISON: authentic worker already holds its outer epoch SHARE.
 IF e.payload_text::jsonb->>'state' NOT IN('OPEN','POISONED') THEN RAISE EXCEPTION '187 xid journal exact epoch' USING ERRCODE='55000';END IF;
 SELECT * INTO STRICT m FROM ordinary187_private.journal WHERE(root_key,epoch,id)=(root0,epoch0,member0) AND kind='member';b:=m.payload_text::jsonb;
 IF b->>'state'<>'RESERVED' OR b->>'token_hash' IS DISTINCT FROM ordinary187_private.token_sha(member_token) OR xid0 IS NULL OR pg_xact_status(xid0) IS DISTINCT FROM 'in progress' OR NOT EXISTS(SELECT FROM pg_stat_activity WHERE pid=(b->>'backend_pid')::integer AND backend_start=(b->>'backend_start')::timestamptz AND datname=current_database() AND backend_xid=xid0::xid) THEN RAISE EXCEPTION '187 actual active worker xid' USING ERRCODE='42501';END IF;
 b:=b||jsonb_build_object('state','ACTIVE','xid',xid0::text);PERFORM ordinary187_private.put(root0,epoch0,member0,'member',m.tenant_id,m.actor_id,m.api_key_id,b);
END $xid187$;

