DECLARE g jsonb;n bigint;id0 uuid;last0 record;body0 jsonb;
BEGIN
 PERFORM public.ordinary187_owner_context();
 IF root0 IS NULL OR root0 !~ '^[a-f0-9]{64}$' OR keys0 IS DISTINCT FROM ARRAY[(('x'||substr(root0,1,8))::bit(32))::integer,(('x'||substr(root0,9,8))::bit(32))::integer]::integer[] OR array_length(keys0,1) IS DISTINCT FROM 2 OR epoch_token IS NULL OR epoch_token !~ '^[a-f0-9]{64}$' OR release0 IS NULL OR release0 !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION '187 epoch input shape' USING ERRCODE='22023';END IF;
 IF NOT pg_try_advisory_xact_lock(keys0[1],keys0[2]) THEN RAISE EXCEPTION '187 root busy' USING ERRCODE='55P03';END IF;
 g:=public.ordinary182_owner_gate();IF g->>'release_sha256' IS DISTINCT FROM release0 THEN RAISE EXCEPTION '187 exact approved source' USING ERRCODE='55000';END IF;
 SELECT * INTO last0 FROM ordinary187_private.journal WHERE root_key=root0 AND kind='epoch' ORDER BY epoch DESC LIMIT 1 FOR UPDATE;
 -- No join/new generation hides an unfinished predecessor. Multi-process joining is a separate explicit API, not implicit adoption.
 IF FOUND AND last0.payload_text::jsonb->>'state' IS DISTINCT FROM 'CLOSED' THEN RAISE EXCEPTION '187 unresolved predecessor epoch' USING ERRCODE='55000';END IF;
 IF EXISTS(SELECT FROM ordinary187_private.journal WHERE root_key=root0 AND kind IN('member','io') AND payload_text::jsonb->>'state' NOT IN('COMMITTED','ROLLED_BACK','DRAINED')) THEN RAISE EXCEPTION '187 historical unresolved journal' USING ERRCODE='55000';END IF;
 n:=coalesce(last0.epoch,0)+1;id0:=gen_random_uuid();body0:=jsonb_build_object('state','OPEN','keys',to_jsonb(keys0),'token_hash',ordinary187_private.token_sha(epoch_token),'generation',g,'release_sha256',release0,'original_count',0,'opened_at',clock_timestamp());
 PERFORM ordinary187_private.put(root0,n,id0,'epoch',t,u,k,body0);
 RETURN jsonb_build_object('root_key',root0,'epoch',n::text,'epoch_id',id0,'generation',g);
END

